import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        // cnt[i*26+c]: occurrences of letter c in s[0..i)
        int[] cnt = new int[(n + 1) * 26];
        for (int i = 0; i < n; i++) {
            System.arraycopy(cnt, i * 26, cnt, (i + 1) * 26, 26);
            cnt[(i + 1) * 26 + s.charAt(i) - 'a']++;
        }
        long ans = 0;
        int p = n; // s[p..] has already become all tail
        char tail = 0;
        int r = n - 1;
        while (r >= 0) {
            int l = r;
            while (l > 0 && s.charAt(l - 1) == s.charAt(r)) l--;
            if (r - l + 1 >= 2) {
                // this run spreads right over every character that differs from it
                char y = s.charAt(r);
                int same = cnt[p * 26 + y - 'a'] - cnt[(r + 1) * 26 + y - 'a'];
                ans += p - (r + 1) - same;
                if (p < n && tail != y) ans += n - p;
                p = l;
                tail = y;
            }
            r = l - 1;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	s := nextToken()
	n := len(s)
	// cnt[i*26+c]: occurrences of letter c in s[0:i]
	cnt := make([]int32, (n+1)*26)
	for i := 0; i < n; i++ {
		copy(cnt[(i+1)*26:(i+2)*26], cnt[i*26:(i+1)*26])
		cnt[(i+1)*26+int(s[i]-'a')]++
	}
	var ans int64
	p := n // s[p:] has already become all tail
	var tail byte
	for r := n - 1; r >= 0; {
		l := r
		for l > 0 && s[l-1] == s[r] {
			l--
		}
		if r-l+1 >= 2 {
			// this run spreads right over every character that differs from it
			y := int(s[r] - 'a')
			same := cnt[p*26+y] - cnt[(r+1)*26+y]
			ans += int64(p - (r + 1) - int(same))
			if p < n && tail != s[r] {
				ans += int64(n - p)
			}
			p, tail = l, s[r]
		}
		r = l - 1
	}
	fmt.Println(ans)
}
